    ('system-design', 'Pipeline stage keeps running out of memory', 'Give the enrichment stage unlimited memory for its buffer', 'Give the enrichment stage unlimited memory for its buffer so it can never run out'),
    ('system-design', 'Pipeline stage keeps running out of memory', 'Drop the enrichment stage''s input silently whenever it is busy', 'Drop the enrichment stage''s input silently whenever that stage is too busy to keep up'),
    ('system-design', 'Pipeline stage keeps running out of memory', 'Apply backpressure with bounded buffers so upstream stages slow down when the enrichment stage falls behind', 'Apply backpressure with bounded buffers so upstream stages slow down when enrichment lags'),
    ('system-design', 'Pipeline stage keeps running out of memory', 'Restart the pipeline automatically every time it runs out of memory', 'Restart the pipeline automatically every time it runs out of memory, replaying from the last offset'),
    ('system-design', 'Order events processed out of order', 'Add a timestamp to each event and have consumers sleep until earlier events arrive', 'Add a timestamp to each event and have every consumer sleep until the earlier events arrive'),
