    ('system-design', 'Friend still sees your old username', 'A race condition that will eventually corrupt the username', 'A race condition that will eventually corrupt the stored username in both regions if left alone'),
    ('system-design', 'Friend still sees your old username', 'A caching bug, since databases always return the latest write', 'A caching bug, since a correctly working database always returns the latest write to every reader'),
    ('system-design', 'Friend still sees your old username', 'Split-brain, because two regions disagree about a value', 'Split-brain, because the two regions disagree about the value and both believe they are correct'),
    ('system-design', 'Friend still sees your old username', 'Eventual consistency — replicas converge shortly after the write, so briefly stale reads are expected', 'Eventual consistency: replicas converge soon after the write, so brief stale reads are expected'),
    ('system-design', 'Ledger behavior during a partition', 'Disable replication so partitions cannot happen', 'Disable replication between the data centers so that partitions cannot happen'),
    ('system-design', 'Ledger behavior during a partition', 'Choose consistency: reject writes on the side that cannot reach a majority until the partition heals', 'Choose consistency: reject writes on the side that cannot reach a majority until it heals'),
    ('system-design', 'Stale reads from a leaderless store', 'Set W=1 and R=1 but read from the fastest replica', 'Set W=1 and R=1 but always read from whichever replica responds fastest'),
