    ('system-design', 'Stale reads from a leaderless store', 'Set W=3 and R=0 so reads are free once writes finish', 'Set W=3 and R=0 so that reads cost nothing once every replica has the write'),
    ('system-design', 'Paused process still holds the lock', 'Issue an increasing fencing token with each lock grant and have storage reject writes with stale tokens', 'Issue an increasing fencing token with each lock and have storage reject stale tokens'),
    ('system-design', 'Paused process still holds the lock', 'Disable garbage collection on the workers', 'Disable garbage collection on the workers so that pauses like this one can never happen again'),
    ('system-design', 'Paused process still holds the lock', 'Increase the lock timeout so garbage-collection pauses fit inside it', 'Increase the lock timeout so that even long garbage-collection pauses always fit inside it'),
    ('system-design', 'Slow payment provider takes down the site', 'Switching payment providers whenever latency exceeds one second', 'Switching payment providers automatically whenever latency exceeds one second'),
    ('system-design', 'Slow payment provider takes down the site', 'A bigger thread pool so more requests can wait simultaneously', 'A bigger thread pool so that more requests can wait simultaneously for the provider'),
    ('system-design', 'Slow payment provider takes down the site', 'A circuit breaker that fails fast when the payment provider is unhealthy instead of letting threads pile up', 'A circuit breaker that fails fast while the provider is unhealthy, so threads do not pile up'),
    ('system-design', 'Slow payment provider takes down the site', 'Retrying each slow payment call immediately on another thread', 'Retrying each slow payment call immediately on another thread, taken from a separate backup pool'),
    ('system-design', 'Retried payment charges the card twice', 'Disable retries so users must tap the button again themselves', 'Disable retries so users must tap the button again themselves after a timeout'),
    ('system-design', 'Retried payment charges the card twice', 'Make the timeout longer so retries happen less often', 'Make the timeout much longer so that automatic retries happen less often'),
    ('system-design', 'Retried payment charges the card twice', 'Send an idempotency key with the payment so the server detects the retry and returns the original result', 'Send an idempotency key so the server recognizes the retry and returns the original result'),
    ('system-design', 'Synchronized retries prolong the outage', 'Retrying immediately in a loop until the request succeeds', 'Retrying immediately in a tight loop until the request succeeds, so clients recover sooner'),
    ('system-design', 'Synchronized retries prolong the outage', 'Exponential backoff with jitter, so retries spread out randomly instead of arriving in synchronized waves', 'Exponential backoff with jitter, so retries spread out randomly instead of arriving together'),
    ('system-design', 'Synchronized retries prolong the outage', 'A shorter fixed retry interval so clients reconnect sooner', 'A shorter fixed retry interval, so that each client reconnects sooner once the service is back'),
    ('system-design', 'Recommendations down, product page down', 'Move recommendations into the product page''s own code so there is no separate service', 'Move recommendations into the product page''s own code so that there is no separate service to fail'),
    ('system-design', 'Recommendations down, product page down', 'Retry the recommendations call until it succeeds before rendering', 'Retry the recommendations call until it succeeds, and only then render the rest of the product page'),
    ('system-design', 'Recommendations down, product page down', 'Make the recommendations service highly available so it never fails', 'Make the recommendations service highly available with extra replicas so that it never fails'),
    ('system-design', 'One slow endpoint starves all the others', 'Cache the reports so they are only slow the first time', 'Cache the reports so that they are only slow the very first time they are generated'),
    ('system-design', 'One slow endpoint starves all the others', 'Double the shared thread pool so it takes longer to fill up', 'Double the shared thread pool so it takes longer for the report requests to fill it'),
    ('system-design', 'One slow endpoint starves all the others', 'Lower the report endpoint''s timeout to 5 seconds and fail the reports', 'Lower the report endpoint''s timeout to 5 seconds and fail the slow reports instead'),
    ('system-design', 'Overload degrades service for everyone', 'Remove all timeouts so slow requests eventually finish', 'Remove all timeouts so that slow requests are eventually allowed to finish'),
    ('system-design', 'Overload degrades service for everyone', 'Slow all requests equally so the pain is distributed fairly', 'Slow all requests equally so the pain of the overload is distributed fairly'),
    ('system-design', 'Overload degrades service for everyone', 'Queue every incoming request no matter how long the queue grows', 'Queue every incoming request, no matter how long the queue grows or how long each request ends up waiting'),
    ('system-design', 'A scraper is degrading the API', 'Add servers until the scraper''s traffic no longer matters', 'Add servers until the scraper''s traffic no longer affects any of the other clients'),
    ('system-design', 'A scraper is degrading the API', 'Block all traffic from every cloud provider''s IP ranges', 'Block all traffic from every cloud provider''s IP ranges to stop automated clients'),
    ('system-design', 'Five requests to render one screen', 'Cache all five responses on the device for a week', 'Cache all five responses on the device for a week, even though some of the data changes daily'),
    ('system-design', 'Five requests to render one screen', 'Reduce the app''s screen content until one endpoint is enough', 'Reduce the home screen''s content until a single existing endpoint is enough to render all of it'),
    ('system-design', 'Five requests to render one screen', 'Expose one aggregated query (e.g. GraphQL or a backend-for-frontend) returning exactly what the screen needs', 'Add one aggregated endpoint, such as GraphQL or a BFF, returning just what the screen needs'),
    ('system-design', 'Five requests to render one screen', 'Have the app fire the five requests in a loop with retries', 'Have the app fire the five requests in a loop with retries until every one of them succeeds'),
    ('system-design', 'Feed pages repeat and skip items', 'Block new posts from appearing while any user is paginating', 'Block new posts from appearing while any user is paginating through the feed'),
    ('system-design', 'Feed pages repeat and skip items', 'Switch to cursor-based pagination anchored to the last item seen instead of a numeric offset', 'Switch to cursor-based pagination anchored to the last item seen, not a numeric offset'),
    ('system-design', 'Feed pages repeat and skip items', 'Increase the page size so fewer pages are needed', 'Increase the page size so fewer pages are needed and fewer items shift'),
    ('system-design', 'Feed pages repeat and skip items', 'Sort the feed randomly so duplicates are less noticeable', 'Sort the feed randomly so that duplicates are less noticeable to users'),
    ('system-design', 'Rate limit that still allows bursts', 'Use a strict fixed interval of one request every 600 milliseconds', 'Use a strict fixed interval of one request every 600 milliseconds for each client'),
    ('system-design', 'Rate limit that still allows bursts', 'No rate limit, since bursts are legitimate', 'No rate limit at all, since the bursts come from legitimate clients and should never be rejected'),
    ('system-design', 'Every release is all-or-nothing', 'Add a mandatory two-week manual QA cycle before every deploy', 'Add a mandatory two-week manual QA cycle before every single deploy to catch bad releases early'),
    ('system-design', 'Every release is all-or-nothing', 'Deploy to all servers at once but keep a finger on the rollback button', 'Deploy to all servers at once, but keep a finger on the rollback button throughout every deploy'),
    ('system-design', 'Every release is all-or-nothing', 'Canary releases: send a small percentage of traffic to the new version and widen gradually if healthy', 'Canary releases: send a small share of traffic to the new version, widening it if healthy'),
    ('system-design', 'Which of six services made it slow?', 'More detailed logging inside each service, still without correlation IDs', 'More detailed logging inside each of the services, still without any correlation IDs between them'),
    ('system-design', 'Which of six services made it slow?', 'Merging the six services into one so there is only one log', 'Merging the six services into a single service so that there is only one log file to search'),
    ('system-design', 'Which of six services made it slow?', 'A shared spreadsheet where teams paste their log timestamps', 'A shared spreadsheet where every team pastes its log timestamps for each slow request it sees'),
    ('system-design', 'Testing a rewrite without risking users', 'Write more unit tests until confidence is high enough', 'Write more unit tests until the team''s confidence is high enough to ship'),
    ('system-design', 'Testing a rewrite without risking users', 'Mirror production traffic to the new engine in shadow mode and compare its outputs to the old one', 'Mirror production traffic to the new engine in shadow mode and compare its outputs'),
    ('system-design', 'Testing a rewrite without risking users', 'Deploy it to all users and monitor closely for pricing complaints', 'Deploy it to all users at once and monitor closely for incoming pricing complaints'),
    ('system-design', 'Logged out but the token still works', 'Store the JWT in two cookies instead of one for extra safety', 'Store the JWT in two separate cookies instead of one, so a thief would need to steal both of them'),
    ('system-design', 'Logged out but the token still works', 'Use short-lived access tokens with revocable refresh tokens, so revocation takes effect within minutes', 'Use short-lived access tokens with revocable refresh tokens, so revocation applies in minutes'),
    ('system-design', 'Logged out but the token still works', 'Extend the JWT lifetime so users need to log in less often', 'Extend the JWT lifetime so that users need to log in less often, which reduces token exposure')
) AS changes (category_slug, question_title, old_text, new_text)
JOIN categories ON categories.slug = changes.category_slug
JOIN questions
    ON questions.category_id = categories.id
    AND questions.title = changes.question_title
WHERE question_options.question_id = questions.id
    AND question_options.option_text = changes.old_text;

COMMIT;
